import {initAdminSales} from './admin-sales.js';
import {initSupport} from './support.js';
import {initBillingClient} from './billing-client.js';
const $=s=>document.querySelector(s);let billing=null,busy=false;const support=initSupport({container:document.querySelector('.admin-dashboard'),admin:true});
async function api(path,body){const response=await fetch('/api/admin/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store',credentials:'same-origin'});const data=await response.json();if(!response.ok){if(response.status===401&&path!=='login')showLogin();throw Error(data.error||'Não foi possível concluir agora.');}return data;}
const sales=initAdminSales({container:document.querySelector('.admin-dashboard'),api});
function showLogin(){sales.clear();support.reset();billing=null;$('.admin-loading').hidden=true;$('.admin-dashboard').hidden=true;$('.admin-login').hidden=false;$('.login-form input').focus();}
async function dashboard(user){$('.admin-loading').hidden=true;$('.admin-login').hidden=true;$('.admin-dashboard').hidden=false;$('.admin-name').textContent=user.username;support.start();billing=initBillingClient({getState:()=>({draftId:'admin-portal',format:'cartao'})});await billing.ready;await Promise.all([list(),sales.load()]);}
async function start(draftId,format){if(busy)return;busy=true;$('.admin-status').textContent='Preparando seu painel de criação…';document.querySelectorAll('[data-new-format],.admin-continue').forEach(b=>b.disabled=true);try{await billing.adminGrant(draftId,format);location.assign('/?adminDraft='+encodeURIComponent(draftId)+'&formato='+encodeURIComponent(format)+'#atelier');}catch(error){$('.admin-status').textContent=error.message;busy=false;document.querySelectorAll('[data-new-format],.admin-continue').forEach(b=>b.disabled=false);}}
async function list(){const {gifts}=await api('gifts');const mount=$('.admin-gifts');mount.replaceChildren();if(!gifts.length){const p=document.createElement('p');p.textContent='Seu primeiro teste começa nos botões acima.';mount.append(p);}for(const gift of gifts){const article=document.createElement('article');article.className='admin-gift';const copy=document.createElement('div'),name=document.createElement('strong'),detail=document.createElement('p'),actions=document.createElement('div');actions.className='admin-gift-actions';name.textContent=gift.recipient||'Teste '+({livro:'de livro',cartao:'de cartão',convite:'de convite',stories:'de Stories'}[gift.format]||'de presente');detail.textContent=(gift.url?'Publicado':'Rascunho')+' · '+new Date(gift.updatedAt*1000).toLocaleDateString('pt-BR');copy.append(name,detail);const button=document.createElement('button');button.className='admin-continue quiet';button.type='button';button.textContent='Continuar editando';button.addEventListener('click',()=>start(gift.draftId,gift.format));actions.append(button);if(gift.url){const link=document.createElement('a');link.href=gift.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Ver presente';actions.append(link);}article.append(copy,actions);mount.append(article);}}
$('.login-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;$('.login-status').textContent='Entrando…';try{const user=await api('login',{username:form.elements.username.value,password:form.elements.password.value});form.elements.password.value='';$('.login-status').textContent='';await dashboard(user);}catch(error){$('.login-status').textContent=error.message;}finally{button.disabled=false;}});
$('.password-toggle').addEventListener('click',event=>{const button=event.currentTarget,input=document.getElementById(button.dataset.target),show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Ocultar senha':'Mostrar senha';button.setAttribute('aria-pressed',String(show));});
document.querySelectorAll('[data-new-format]').forEach(button=>button.addEventListener('click',()=>start(crypto.randomUUID(),button.dataset.newFormat)));
$('.admin-open-support').addEventListener('click',()=>support.open());
$('.admin-refresh').addEventListener('click',()=>list().catch(error=>$('.admin-status').textContent=error.message));$('.admin-logout').addEventListener('click',async()=>{try{await api('logout',{});showLogin();}catch(error){$('.admin-status').textContent=error.message;}});
$('.password-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),status=$('.password-status');if(form.elements.newPassword.value!==form.elements.confirmation.value){status.textContent='As duas novas senhas precisam ser iguais.';return;}button.disabled=true;try{await api('password',{currentPassword:form.elements.currentPassword.value,newPassword:form.elements.newPassword.value});form.reset();status.textContent='Senha alterada. Os outros acessos da conta foram encerrados.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
api('session').then(user=>user.authenticated?dashboard(user):showLogin()).catch(error=>{showLogin();$('.login-status').textContent=error.message;});

$('.ai-demo-run').addEventListener('click',async event=>{const button=event.currentTarget,status=$('.ai-demo-status'),output=$('.ai-demo-answer');button.disabled=true;status.textContent='Gerando resposta de teste…';output.textContent='';try{const result=await api('ai-demo',{selection:$('#ai-demo-selection').value});output.textContent=result.answer;status.textContent='Exemplo gerado apenas para avaliação interna.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
